BEGIN
  INSERT INTO jejak_data (tabel, aksi, id_baris, lama) VALUES ('usulan_pegawai', 'hapus', OLD.id, json_patch(json_patch(json_patch(json_object('id', OLD.id, 'pegawai_id', OLD.pegawai_id, 'satker', OLD.satker, 'status', OLD.status, 'nomor_surat', OLD.nomor_surat, 'tanggal_surat', OLD.tanggal_surat, 'path_berkas', OLD.path_berkas, 'nama', OLD.nama, 'tempat_lahir', OLD.tempat_lahir, 'tanggal_lahir', OLD.tanggal_lahir, 'jenis_kelamin', OLD.jenis_kelamin, 'pendidikan_terakhir', OLD.pendidikan_terakhir, 'jabatan', OLD.jabatan, 'pangkat', OLD.pangkat, 'golongan_ruang', OLD.golongan_ruang), json_object('eselon', OLD.eselon, 'jenis_jabatan', OLD.jenis_jabatan, 'tmt_golongan', OLD.tmt_golongan, 'mkg_tahun', OLD.mkg_tahun, 'mkg_bulan', OLD.mkg_bulan, 'gaji_pokok', OLD.gaji_pokok, 'tmt_kgb_terakhir', OLD.tmt_kgb_terakhir, 'tmt_kgb_berikutnya', OLD.tmt_kgb_berikutnya, 'nomor_sk_terakhir', OLD.nomor_sk_terakhir, 'tanggal_sk_terakhir', OLD.tanggal_sk_terakhir, 'hukdis_ada', OLD.hukdis_ada, 'hukdis_jenis', OLD.hukdis_jenis, 'hukdis_nomor_sk', OLD.hukdis_nomor_sk, 'hukdis_tmt_mulai', OLD.hukdis_tmt_mulai, 'hukdis_tmt_berakhir', OLD.hukdis_tmt_berakhir)), json_object('hukdis_keterangan', OLD.hukdis_keterangan, 'catatan_upt', OLD.catatan_upt, 'diajukan_oleh', OLD.diajukan_oleh, 'diajukan_at', OLD.diajukan_at, 'ditinjau_oleh', OLD.ditinjau_oleh, 'ditinjau_at', OLD.ditinjau_at, 'alasan_tolak', OLD.alasan_tolak, 'urutan_sisip', OLD.urutan_sisip, 'jenis', OLD.jenis, 'nip', OLD.nip, 'unit_kerja', OLD.unit_kerja, 'path_sk_terakhir', OLD.path_sk_terakhir, 'path_syarat_cpns', OLD.path_syarat_cpns, 'path_sk_pangkat', OLD.path_sk_pangkat, 'path_sk_cpns', OLD.path_sk_cpns)), json_object('dasar_baru_jenis', OLD.dasar_baru_jenis, 'dasar_baru_jenis_kp', OLD.dasar_baru_jenis_kp, 'dasar_baru_nomor_sk', OLD.dasar_baru_nomor_sk, 'dasar_baru_tanggal_sk', OLD.dasar_baru_tanggal_sk, 'dasar_baru_tmt', OLD.dasar_baru_tmt, 'dasar_baru_penetap', OLD.dasar_baru_penetap, 'path_sk_pmk', OLD.path_sk_pmk, 'golongan_acuan', OLD.golongan_acuan, 'mkg_tahun_acuan', OLD.mkg_tahun_acuan, 'mkg_bulan_acuan', OLD.mkg_bulan_acuan, 'keadaan_kgb', OLD.keadaan_kgb, 'penetap_sk_terakhir', OLD.penetap_sk_terakhir)));
END;
